<script setup>
import { onBeforeUnmount, ref } from 'vue';

const props = defineProps({ payload: { type: String, required: true } });
const state = JSON.parse(props.payload);
const author = state.author || {};
const old = state.old || {};
const errors = state.errors || {};
const csrf = document.querySelector('meta[name="csrf-token"]')?.content || '';
const preview = ref(null);
const fileName = ref(state.view === 'edit' ? 'No file chosen' : 'JPG, PNG or WEBP');
let objectUrl;

function choosePhoto(event) {
    const file = event.target.files?.[0];
    if (objectUrl) URL.revokeObjectURL(objectUrl);
    objectUrl = null;
    preview.value = null;
    fileName.value = file?.name || (state.view === 'edit' ? 'No file chosen' : 'JPG, PNG or WEBP');
    if (!file) return;
    if (!file.type.startsWith('image/')) {
        event.target.value = '';
        fileName.value = 'JPG, PNG or WEBP';
        return;
    }
    objectUrl = URL.createObjectURL(file);
    preview.value = objectUrl;
}

function removeAuthor(url) {
    const submit = () => {
        const form = document.createElement('form'); form.method = 'POST'; form.action = url;
        const token = document.createElement('input'); token.type = 'hidden'; token.name = '_token'; token.value = csrf;
        const method = document.createElement('input'); method.type = 'hidden'; method.name = '_method'; method.value = 'DELETE';
        form.append(token, method); document.body.append(form); form.submit();
    };
    if (window.Swal) window.Swal.fire({ title: 'Delete author?', text: 'This action cannot be undone.', icon: 'warning', showCancelButton: true, confirmButtonText: 'Delete', cancelButtonText: 'Cancel', reverseButtons: true }).then((result) => { if (result.isConfirmed) submit(); });
    else if (window.confirm('Delete this author?')) submit();
}

onBeforeUnmount(() => { if (objectUrl) URL.revokeObjectURL(objectUrl); });
</script>

<template>
    <div class="dashboard-section authors-page">
        <template v-if="state.view === 'index'">
            <section class="authors-hero"><div class="authors-hero-content"><span class="authors-hero-badge"><i class="bi bi-person-lines-fill"></i> Author Directory</span><h1>Every author, beautifully organised.</h1><p>Manage your marketplace authors, book relationships and author information from one organised workspace.</p></div><div class="authors-hero-mark"><i class="bi bi-person-badge"></i></div></section>
            <div v-if="state.success" class="alert alert-success">{{ state.success }}</div>
            <section class="authors-stats"><div v-for="stat in [{label:'Total Authors',value:state.stats.total,color:'stat-blue',icon:'bi-people'},{label:'With Books',value:state.stats.with_books,color:'stat-green',icon:'bi-book'},{label:'No Books',value:state.stats.without_books,color:'stat-orange',icon:'bi-bookmark-x'},{label:'Total Books',value:state.stats.books,color:'stat-purple',icon:'bi-collection'}]" :key="stat.label" class="author-stat-card" :class="stat.color"><div class="author-stat-content"><span>{{ stat.label }}</span><strong>{{ stat.value }}</strong></div><div class="author-stat-icon"><i class="bi" :class="stat.icon"></i></div></div></section>
            <section class="dashboard-panel authors-panel"><div class="authors-panel-header"><div class="authors-heading-content"><span class="eyebrow">Author directory</span><h5>All Authors</h5><p>Search and manage every author registered on SecondBook.</p></div><div class="authors-header-action"><a :href="state.urls.create" class="authors-add-btn"><i class="bi bi-plus-lg"></i><span>Add Author</span></a></div></div>
                <form method="GET" :action="state.urls.index" class="author-filters"><div class="author-filter-group author-filter-search"><label for="author-search">Search</label><div class="author-search-field"><i class="bi bi-search"></i><input id="author-search" name="search" :value="state.search" type="text" placeholder="Author name..." autocomplete="off"></div></div><div class="author-filter-actions"><button type="submit" class="author-filter-btn"><i class="bi bi-search"></i><span>Search</span></button><a v-if="state.search !== ''" :href="state.urls.index" class="author-clear-filter"><i class="bi bi-x-lg"></i><span>Clear</span></a></div></form>
                <div class="authors-table-wrap"><table class="authors-table"><thead><tr><th class="authors-col-id">#</th><th class="authors-col-author">Author</th><th class="authors-col-books">Books</th><th class="authors-col-created">Created</th><th class="authors-col-updated">Updated</th><th class="authors-col-actions">Actions</th></tr></thead><tbody>
                    <tr v-for="(item,index) in state.authors" :key="item.id"><td><span class="author-id">{{ state.pagination.first + index }}</span></td><td><div class="author-item-cell"><div class="author-avatar">{{ (item.name || 'U').slice(0,1).toUpperCase() }}</div><div class="author-item-info"><strong :title="item.name">{{ item.name }}</strong><small>Author #{{ item.id }}</small></div></div></td><td><span v-if="item.books_count" class="author-books-pill has-books"><i class="bi bi-book"></i>{{ item.books_count }} {{ item.books_count === 1 ? 'Book' : 'Books' }}</span><span v-else class="author-books-pill no-books"><i class="bi bi-bookmark-x"></i>No Books</span></td><td><div class="author-date-info"><strong>{{ item.created }}</strong><small>{{ item.created_time }}</small></div></td><td><div class="author-date-info"><strong>{{ item.updated }}</strong><small>{{ item.updated_time }}</small></div></td><td><div class="author-actions"><a :href="item.show_url" class="author-action-btn author-view-btn" title="View author"><i class="bi bi-eye"></i></a><a :href="item.edit_url" class="author-action-btn author-edit-btn" title="Edit author"><i class="bi bi-pencil"></i></a><button type="button" class="author-action-btn author-delete-btn" title="Delete author" @click="removeAuthor(item.delete_url)"><i class="bi bi-trash"></i></button></div></td></tr>
                    <tr v-if="!state.authors.length"><td colspan="6"><div class="authors-empty-state"><div class="authors-empty-icon"><i class="bi bi-person-x"></i></div><strong>No authors found</strong><span>Try changing your search or add a new author.</span><a :href="state.urls.create" class="authors-empty-btn"><i class="bi bi-plus-lg"></i>Add Author</a></div></td></tr>
                </tbody></table></div>
                <div v-if="state.pagination.last_page > 1" class="authors-pagination"><div class="authors-pagination-info">Showing <strong>{{ state.pagination.first }}</strong> to <strong>{{ state.pagination.last }}</strong> of <strong>{{ state.pagination.total }}</strong> authors</div><nav class="authors-pagination-pages" aria-label="Authors pagination"><a :href="state.pagination.previous || undefined" class="authors-pager-btn" :class="{disabled:!state.pagination.previous}"><i class="bi bi-chevron-left"></i></a><a v-for="(url,page) in state.pagination.pages" :key="page" :href="url" class="authors-pager-btn" :class="{active:Number(page)===Number(state.pagination.current)}">{{ page }}</a><a :href="state.pagination.next || undefined" class="authors-pager-btn" :class="{disabled:!state.pagination.next}"><i class="bi bi-chevron-right"></i></a></nav></div>
            </section>
        </template>

        <template v-else-if="state.view === 'create' || state.view === 'edit'">
            <section class="authors-hero authors-hero-compact"><div class="authors-hero-content"><span class="authors-hero-badge"><i class="bi bi-person-vcard"></i>{{ state.view === 'create' ? 'New author' : 'Author Management' }}</span><h1>{{ state.view === 'create' ? 'Add a new author' : 'Edit Author' }}</h1><p>{{ state.view === 'create' ? 'Create an author profile, add a short biography, upload a photo and set the author’s status.' : 'Update author information, biography, photo and publication status.' }}</p></div><div class="authors-hero-mark"><i class="bi bi-person"></i></div></section>
            <div v-if="Object.keys(errors).length" class="author-form-alert" role="alert"><i class="bi bi-exclamation-triangle"></i><div><strong>Please fix the following errors:</strong><ul><template v-for="(messages,key) in errors" :key="key"><li v-for="message in messages" :key="message">{{ message }}</li></template></ul></div></div>
            <form :action="state.view === 'create' ? state.urls.store : state.urls.update" method="POST" enctype="multipart/form-data" novalidate><input type="hidden" name="_token" :value="csrf"><input v-if="state.view === 'edit'" type="hidden" name="_method" value="PUT"><div class="author-form-layout">
                <div class="author-form-main"><section class="dashboard-panel authors-panel author-form-panel"><div class="authors-panel-header"><div class="authors-heading-content"><span class="eyebrow">Step 1</span><h5>Author information</h5><p>Add the author’s name and biography.</p></div><a :href="state.urls.index" class="author-clear-filter"><i class="bi bi-arrow-left"></i><span>Back to authors</span></a></div><div class="author-form-body"><div class="author-form-grid"><div class="author-field author-field-full"><label for="author-name">Author name <span class="author-required">*</span></label><input id="author-name" name="name" class="author-input" :class="{'is-invalid':errors.name}" :value="old.name" placeholder="Enter author name" maxlength="255" required autofocus><span v-for="error in errors.name" :key="error" class="author-field-error">{{ error }}</span></div><div class="author-field author-field-full"><label for="author-bio">Biography</label><textarea id="author-bio" name="bio" class="author-input author-textarea" :class="{'is-invalid':errors.bio}" :value="old.bio" rows="6" maxlength="3000" placeholder="Write a short biography about the author..."></textarea><span v-for="error in errors.bio" :key="error" class="author-field-error">{{ error }}</span></div></div></div></section>
                    <section v-if="state.view === 'create'" class="dashboard-panel authors-panel author-form-panel"><div class="authors-panel-header"><div class="authors-heading-content"><span class="eyebrow">Step 2</span><h5>Visibility</h5><p>Choose whether this author should be visible and available in the administration.</p></div></div><div class="author-form-body"><div class="author-form-grid"><div class="author-field"><label for="author-status">Author status</label><select id="author-status" name="status" class="author-input author-select" :class="{'is-invalid':errors.status}"><option value="1" :selected="String(old.status)==='1'">Active</option><option value="0" :selected="String(old.status)==='0'">Inactive</option></select><span v-for="error in errors.status" :key="error" class="author-field-error">{{ error }}</span></div></div></div></section>
                </div>
                <aside class="author-form-side"><section class="dashboard-panel authors-panel author-form-panel"><div class="authors-panel-header"><div class="authors-heading-content"><span class="eyebrow">Media</span><h5>Author photo</h5><p>Upload a profile photo for the author.</p></div></div><div class="author-form-body"><div class="author-photo-preview"><img v-if="preview" :src="preview" alt="Author photo preview"><img v-else-if="state.view==='edit' && author.photo" :src="author.photo" :alt="author.name"><div v-else class="author-photo-preview-empty"><i class="bi bi-person"></i><span>No photo selected</span></div></div><div class="author-file-upload"><input type="file" name="photo" id="authorPhotoInput" class="author-file-native" accept="image/jpeg,image/png,image/webp" @change="choosePhoto"><label for="authorPhotoInput" class="author-file-label"><span class="author-file-icon"><i class="bi bi-cloud-arrow-up"></i></span><span class="author-file-content"><span class="author-file-title">Upload photo</span><span class="author-file-name">{{ fileName }}</span></span><span class="author-file-button">Browse</span></label></div><span v-for="error in errors.photo" :key="error" class="author-field-error">{{ error }}</span></div></section>
                    <section class="dashboard-panel authors-panel author-form-panel"><div class="authors-panel-header"><div class="authors-heading-content"><span class="eyebrow">Publishing</span><h5>Status</h5></div></div><div class="author-form-body"><div v-if="state.view==='edit'" class="authors-status-card"><div class="authors-status-info"><span class="authors-status-icon"><i class="bi bi-check-circle"></i></span><div><strong>Active Author</strong><span>Active authors are available for book assignments.</span></div></div><label class="authors-switch"><input type="checkbox" name="status" value="1" :checked="['1',1,true].includes(old.status)"><span class="authors-switch-slider"></span></label></div><div v-else class="author-form-actions"><button type="submit" class="authors-add-btn author-submit-btn"><i class="bi bi-check-lg"></i><span>Save author</span></button><a :href="state.urls.index" class="author-clear-filter author-cancel-btn">Cancel</a></div><div v-if="state.view==='edit'" class="authors-form-actions"><a :href="state.urls.index" class="authors-cancel-btn"><i class="bi bi-x-lg"></i>Cancel</a><button type="submit" class="authors-add-btn"><i class="bi bi-check-circle"></i>Update Author</button></div></div></section>
                </aside>
            </div></form>
        </template>

        <template v-else>
            <section class="authors-hero authors-hero-compact"><div class="authors-hero-content"><span class="authors-hero-badge"><i class="bi bi-person-vcard"></i>Author details</span><h1>{{ author.name }}</h1><p>Review author information, biography, status and account activity.</p></div><div class="authors-hero-mark"><i class="bi bi-person"></i></div></section>
            <section class="authors-panel author-show-panel"><div class="authors-panel-header"><div class="authors-heading-content"><span class="eyebrow">Author information</span><h5>{{ author.name }}</h5><p>Complete information about this author.</p></div><div class="authors-header-action"><a :href="state.urls.index" class="author-cancel-btn"><i class="bi bi-arrow-left"></i>Back to authors</a><a :href="state.urls.edit" class="authors-add-btn"><i class="bi bi-pencil"></i>Edit Author</a></div></div>
                <div class="author-show-body"><div class="author-show-photo-section"><div class="author-show-section-label">Author photo</div><div v-if="author.photo" class="author-show-photo-wrapper"><img :src="author.photo" :alt="author.name" class="author-show-photo" loading="lazy"></div><div v-else class="author-show-no-photo"><i class="bi bi-person"></i><span>No photo</span></div></div><div class="author-show-information"><div class="author-show-info-card"><span class="author-show-info-label">Author ID</span><strong class="author-show-info-value author-show-id">#{{ author.id }}</strong></div><div class="author-show-info-card"><span class="author-show-info-label">Name</span><strong class="author-show-info-value">{{ author.name }}</strong></div><div class="author-show-info-card"><span class="author-show-info-label">Status</span><div class="author-show-info-value"><span class="author-show-status" :class="author.status?'active':'inactive'"><span class="status-dot"></span>{{ author.status?'Active':'Inactive' }}</span></div></div><div class="author-show-info-card"><span class="author-show-info-label">Created</span><strong class="author-show-info-value">{{ author.created }}</strong></div><div class="author-show-info-card"><span class="author-show-info-label">Last updated</span><strong class="author-show-info-value">{{ author.updated }}</strong></div></div></div>
                <div class="author-show-description"><div class="author-show-description-header"><div><span class="eyebrow">Biography</span><h5>About the author</h5></div><i class="bi bi-journal-text"></i></div><div class="author-show-description-content">{{ author.bio || 'No biography has been added for this author.' }}</div></div>
                <div class="author-show-footer"><div class="author-show-footer-info">Author <strong>#{{ author.id }}</strong></div><div class="author-show-footer-actions"><a :href="state.urls.index" class="author-show-footer-btn" title="Back to authors"><i class="bi bi-arrow-left"></i></a><a :href="state.urls.edit" class="author-show-footer-btn active" title="Edit author"><i class="bi bi-pencil"></i></a></div></div>
            </section>
        </template>
    </div>
</template>
